begin;
do $$
declare a uuid;op uuid;m uuid;o uuid;j uuid;b uuid;j2 uuid;v timestamptz;uid uuid:=gen_random_uuid();session uuid:=gen_random_uuid();r jsonb;payload jsonb;denied boolean;
begin
 insert into public.impjo_principals(kind,state,name) values('STAFF','APPROVED','QA MGMT ADMIN') returning id into a;
 insert into public.impjo_principals(kind,state,name) values('STAFF','APPROVED','QA MGMT OP') returning id into op;
 insert into public.impjo_principals(kind,state,name) values('LINE','APPROVED','QA MGMT MESS') returning id into m;
 insert into public.impjo_principals(kind,state,name) values('LINE','APPROVED','QA MGMT OUTSOURCE') returning id into o;
 insert into public.impjo_roles values(a,'ADMIN'),(op,'OPERATOR'),(m,'MESS'),(o,'OUTSOURCE');
 insert into auth.users(id,email,email_confirmed_at) values(uid,'qa-'||uid||'@example.invalid',now());
 insert into public.impjo_staff_identities values(uid,op);
 insert into auth.sessions(id,user_id) values(session,uid);
 r:=public.impjo_api(op,'create',jsonb_build_object('job_date',(now() at time zone 'Asia/Bangkok')::date,'contact','QA','phone','001','purpose','QA','bls',jsonb_build_array(jsonb_build_object('number','QA-'||uid,'consignee','QA','destination','QA'))));j:=(r->>'id')::uuid;
 select id into b from public.impjo_bls where job_id=j;
 perform public.impjo_api(a,'assign',jsonb_build_object('bl_id',b,'role','MESS','principal_id',m));
 perform public.impjo_api(op,'status',jsonb_build_object('bl_id',b,'status','IN_PROGRESS'));
 select updated_at into v from public.impjo_jobs where id=j;
 payload:=jsonb_build_object('id',j,'version',v,'job_date',(now() at time zone 'Asia/Bangkok')::date,'contact','QA edited','phone','001','purpose','EDIT','notes','QA','bls',jsonb_build_array(jsonb_build_object('id',b,'number','QA-'||uid,'consignee','Edited','destination','QA','status','COMPLETED')));
 perform public.impjo_manage(op,'edit_job',payload);
 assert (select status='IN_PROGRESS' from public.impjo_bls where id=b),'Job edit changed BL status';
 assert (select consignee='Edited' from public.impjo_bls where id=b),'Job edit did not update BL';
 assert exists(select 1 from public.impjo_assignments where bl_id=b and principal_id=m and revoked_at is null),'Edit lost assignment';
 denied:=false;begin perform public.impjo_manage(op,'edit_job',payload);exception when invalid_parameter_value then denied:=true;end;assert denied,'Stale job edit overwrote changes';
 denied:=false;begin perform public.impjo_manage(o,'export_jobs',jsonb_build_object('from',(now() at time zone 'Asia/Bangkok')::date,'to',(now() at time zone 'Asia/Bangkok')::date));exception when insufficient_privilege then denied:=true;end;assert denied,'OUTSOURCE exported staff data';
 select updated_at into v from public.impjo_jobs where id=j;
 perform public.impjo_manage(op,'archive_job',jsonb_build_object('id',j,'version',v));
 assert not public.impjo_visible_bl(m,b),'Archived job still visible to MESS';
 denied:=false;begin perform public.impjo_api(a,'detail',jsonb_build_object('id',j));exception when no_data_found then denied:=true;end;assert denied,'Archived detail accessible';
 denied:=false;begin perform public.impjo_api(m,'status',jsonb_build_object('bl_id',b,'status','COMPLETED'));exception when no_data_found then denied:=true;end;assert denied,'Archived BL accepted status write';
 r:=public.impjo_manage(op,'export_jobs',jsonb_build_object('from',(now() at time zone 'Asia/Bangkok')::date,'to',(now() at time zone 'Asia/Bangkok')::date));
 assert not exists(select 1 from jsonb_array_elements(r->'rows') x where x->>'bl_number'='QA-'||uid),'Archived job exported';
 perform public.impjo_manage(op,'restore_job',jsonb_build_object('id',j));
 assert public.impjo_visible_bl(m,b),'Restored assigned job not visible';
 r:=public.impjo_manage(op,'export_jobs',jsonb_build_object('from',(now() at time zone 'Asia/Bangkok')::date,'to',(now() at time zone 'Asia/Bangkok')::date));
 assert exists(select 1 from jsonb_array_elements(r->'rows') x where x->>'bl_number'='QA-'||uid),'Inclusive date export missed job';
 denied:=false;begin perform public.impjo_manage(a,'archive_account',jsonb_build_object('id',a));exception when insufficient_privilege then denied:=true;end;assert denied,'Admin archived self';
 denied:=false;begin perform public.impjo_manage(op,'archive_account',jsonb_build_object('id',m));exception when insufficient_privilege then denied:=true;end;assert denied,'OPERATOR archived account';
 perform public.impjo_manage(a,'archive_account',jsonb_build_object('id',op));
 assert not exists(select 1 from auth.sessions where id=session),'Archived staff Auth session remained active';
 assert (select state='DISABLED' and archived_at is not null from public.impjo_principals where id=op),'Archived account still active';
 perform public.impjo_manage(a,'restore_account',jsonb_build_object('id',op));
 assert (select state='PENDING' and archived_at is null from public.impjo_principals where id=op),'Restore bypassed approval';
 assert not exists(select 1 from public.impjo_roles where principal_id=op),'Restore retained privileged role';
 assert exists(select 1 from public.impjo_events where action='EDIT_JOB' and actor_id=op and target_id=j),'Edit audit missing';
 assert not has_function_privilege('anon','public.impjo_manage(uuid,text,jsonb)','EXECUTE'),'Anon management access';
end $$;
rollback;
select 'PASS: optimistic editing, unchanged status/assignments, archive isolation, date export, recoverable accounts and Auth session revocation; fixtures rolled back.' as result;
